package app.chataibox.mobile;
import org.json.*;import java.net.URI;import java.io.IOException;
public final class Providers {
 public static JSONObject resolve(JSONObject settings,String id)throws Exception{if(id==null||id.isEmpty())id=settings.optString("activeProviderId","deepseek");if(id.equals("deepseek"))return new JSONObject().put("id","deepseek").put("baseUrl","https://api.deepseek.com").put("apiKey",settings.optString("apiKey"));JSONArray all=settings.optJSONArray("providers");if(all!=null)for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optString("id").equals(id)){JSONObject p=all.getJSONObject(i);validate(p);return p;}throw new IOException("请先在本机配置此模型提供方");}
 public static void validate(JSONObject p)throws Exception{URI u=new URI(p.getString("baseUrl"));String host=u.getHost();boolean local="localhost".equals(host)||"127.0.0.1".equals(host)||"[::1]".equals(host);if(host==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||!("https".equals(u.getScheme())||local&&"http".equals(u.getScheme())))throw new IOException("提供方地址须为 HTTPS（本机接口可使用 HTTP）");JSONArray models=p.getJSONArray("models");if(p.optString("id").isEmpty()||p.optString("id").equals("deepseek")||models.length()==0||models.length()>100)throw new IOException("提供方配置无效");for(int i=0;i<models.length();i++)if(models.getString(i).isEmpty()||models.getString(i).length()>160)throw new IOException("模型名称无效");}
 public static JSONObject body(JSONObject body,JSONObject provider)throws Exception{if(!provider.optString("id").equals("deepseek")){body.remove("stream_options");String thinking=provider.optString("thinking","none");if(thinking.equals("effort"))body.put("reasoning_effort",body.optJSONObject("thinking")!=null&&body.getJSONObject("thinking").optString("type").equals("enabled")?"high":"none");if(!thinking.equals("deepseek"))body.remove("thinking");if(!provider.optBoolean("search")){body.remove("tools");body.remove("web_search_options");}}return body;}
}
